import pandas as pd
import numpy as np

train = pd.read_csv('train.csv')
test = pd.read_csv('test.csv')
feature_cols = [c for c in train.columns if c != 'target']
X_train = train[feature_cols].values
y_train = train['target'].values
X_test = test[feature_cols].values
y_test = test['target'].values

mu = X_train.mean(axis=0)
sigma = X_train.std(axis=0) + 1e-8
X_train_s = (X_train - mu) / sigma
X_test_s = (X_test - mu) / sigma

# Random forest-like approach: bootstrap + random feature subset + tree
np.random.seed(42)
n = len(y_train)
d = X_train.shape[1]

def find_best_split(X, y, feat_subset):
    best_gini = 1.0
    best_j = feat_subset[0]
    best_t = 0
    for j in feat_subset:
        vals = np.sort(np.unique(X[:, j]))
        for idx in range(len(vals)-1):
            t = (vals[idx] + vals[idx+1]) / 2
            left = X[:, j] <= t
            right = ~left
            if np.sum(left) == 0 or np.sum(right) == 0:
                continue
            nl, nr = np.sum(left), np.sum(right)
            p1l = np.mean(y[left])
            p1r = np.mean(y[right])
            gini = (nl * 2*p1l*(1-p1l) + nr * 2*p1r*(1-p1r)) / (nl + nr)
            if gini < best_gini:
                best_gini = gini
                best_j = j
                best_t = t
    return best_j, best_t

def build_tree(X, y, depth=1, max_depth=3, max_features=7):
    if depth > max_depth or len(np.unique(y)) <= 1 or len(y) < 4:
        return int(np.round(np.mean(y)))
    feat_subset = np.random.choice(d, min(max_features, d), replace=False)
    j, t = find_best_split(X, y, feat_subset)
    left = X[:, j] <= t
    right = ~left
    if np.sum(left) < 2 or np.sum(right) < 2:
        return int(np.round(np.mean(y)))
    return {
        'feature': j, 'threshold': t,
        'left': build_tree(X[left], y[left], depth+1, max_depth, max_features),
        'right': build_tree(X[right], y[right], depth+1, max_depth, max_features),
    }

def tree_predict(tree, x):
    if isinstance(tree, int):
        return tree
    if x[tree['feature']] <= tree['threshold']:
        return tree_predict(tree['left'], x)
    return tree_predict(tree['right'], x)

for n_trees in [50, 100, 200, 500]:
    for max_depth in [2, 3, 4]:
        for max_features in [5, 7, 10, 15]:
            np.random.seed(42)
            votes = np.zeros((len(X_test), 2))
            for _ in range(n_trees):
                boot_idx = np.random.choice(n, n, replace=True)
                tree = build_tree(X_train[boot_idx], y_train[boot_idx], max_depth=max_depth, max_features=max_features)
                for i in range(len(X_test)):
                    pred = tree_predict(tree, X_test[i])
                    votes[i, pred] += 1
            preds = np.argmax(votes, axis=1)
            acc = np.mean(preds == y_test)
            if acc >= 0.8:
                print(f'RF n={n_trees}, depth={max_depth}, mf={max_features}: acc={acc:.3f}')
"

